Find the exact value of $\underset{\sim}{a}\cdot\underset{\sim}{b}$ for the vectors shown.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=1.2]
\usetikzlibrary{angles, quotes, arrows.meta}
\coordinate (O) at (0,0);
\coordinate (A) at (4.2,0);
\coordinate (B) at (150:1.75);
\draw[-{Stealth}] (O) -- (A) node[midway, below] {$|\underset{\sim}{a}|=12$};
\draw[-{Stealth}] (O) -- (B) node[midway, above left] {$|\underset{\sim}{b}|=5$};
\pic[draw, "$150^{\circ}$", angle radius=0.9cm, angle eccentricity=1.6] {angle = A--O--B};
\end{tikzpicture}
[/tikz]
